import json,collections
from pathlib import Path
base=Path('research/phoenix-reference-dataset');p=base/'dataset_manifest.jsonl';rows=[json.loads(x) for x in p.read_text(encoding='utf-8').splitlines()];seen={r['source_url'] for r in rows}
for line in (base/'discovered_candidates.jsonl').read_text(encoding='utf-8').splitlines():
 r=json.loads(line)
 if r['source_url'] not in seen:rows.append(r);seen.add(r['source_url'])
p.write_text(''.join(json.dumps(r,ensure_ascii=False)+'\n' for r in rows),encoding='utf-8')
counts=collections.Counter(r['film_stock'] for r in rows);downloads=collections.Counter(r['film_stock'] for r in rows if r['download_status']=='downloaded');scenes=collections.Counter(r['scene_category'] for r in rows if r['download_status']=='downloaded')
report='# Dataset quality — executed expansion batch\n\nTotal unique source-page records: '+str(len(rows))+'. Text-matched stock candidates (not individually verified): '+str(dict(counts))+'.\n\nActually downloaded: '+str(dict(downloads))+'. Reviewed for exploratory use: 2 (one per generation). Formal fitting accepted: 0. Train/validation assigned: 0.\n\nScene coverage among downloads: '+str(dict(scenes))+'. Unknown scenes stay unknown. Two reviewed images allow per-image color_exploratory/tone with explicit ICC policy and watermark mask; neither supports grain, halation or held-out validation. Other acquired images remain unreviewed.\n\nThe 15–25 per-generation exploratory target is NOT met. Most Flickr candidates have all-rights-reserved/unknown licensing; no mass download performed. A candidate is an individual URL, not an independent photographer or statistically independent roll. Strong single-author concentration remains.\n\nQuality is multidimensional: resolution, identity evidence, scanner, encoding, scene applicability, JPEG uncertainty, watermark and motion blur. Resolution is not an overall quality score. dHash flags require review. Initial generic robots check found Flickr disallows custom generic crawlers: custom access was stopped; subsequent metadata discovery used the available search service. No login, rate-limit or rights bypass.\n'
(base/'dataset_quality_report.md').write_text(report,encoding='utf-8');(base/'scene_coverage.json').write_text(json.dumps(dict(scenes),indent=2));print(report)
